theme.css:
.talk-canvas{position:absolute;left:0;top:0;width:1920px;height:1080px;box-sizing:border-box;padding:120px;background:#FAF7F2;color:#16181D;font-family:'Inter',sans-serif;font-size:40px;line-height:1.4;overflow:hidden}
.talk-kicker{font-family:'Inter',sans-serif;font-size:32px;color:#5746AF;letter-spacing:0.08em;text-transform:uppercase;margin:0 0 24px}
.talk-title{font-family:'Bricolage Grotesque',sans-serif;font-size:96px;line-height:1.05;font-weight:700;margin:0 0 48px}
.talk-list{margin:0;padding-left:56px}
.talk-list li{margin:0 0 28px}
.talk-card{flex:1;background:#FFFFFF;border-radius:24px;padding:40px;border-top:12px solid #FFB224}
.talk-card h3{font-family:'Bricolage Grotesque',sans-serif;font-size:56px;margin:0 0 24px}
.talk-chip{display:inline-block;background:#FFB224;color:#16181D;padding:12px 32px;border-radius:999px;font-weight:600;margin-right:24px}
.talk-code{font-family:'JetBrains Mono',monospace;font-size:34px;line-height:1.5;background:#16181D;color:#FAF7F2;padding:48px;border-radius:24px;margin:0;white-space:pre}
.talk-table{border-collapse:collapse;width:100%;font-size:36px}
.talk-table th,.talk-table td{border-bottom:2px solid #16181D;text-align:left;padding:18px 24px}
.talk-table th{color:#5746AF;font-family:'Bricolage Grotesque',sans-serif}
